#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<double> block_sums(static_cast<std::size_t>(max_threads), 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(T) - 1) / static_cast<std::size_t>(T);
        const std::size_t start = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (start + chunk < n) ? (start + chunk) : n;

        double local_sum = 0.0;
        for (std::size_t i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = local_sum;
        }

        block_sums[tid] = local_sum;

        #pragma omp barrier

        double offset = 0.0;
        for (int t = 0; t < tid; ++t) {
            offset += block_sums[t];
        }

        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
